/// `BASE64URL(SHA256(verifier))`, the S256 `code_challenge`.
pub fn pkce_challenge(verifier: &str) -> String {
    URL_SAFE_NO_PAD.encode(Sha256::digest(verifier.as_bytes()))
}

fn random_token(bytes: usize) -> Result<String, CliError> {
    let mut buffer = vec![0; bytes];
    getrandom::getrandom(&mut buffer)
        .map_err(|error| CliError::internal(format!("no randomness: {error}")))?;
    Ok(URL_SAFE_NO_PAD.encode(buffer))
}

#[derive(Deserialize)]
struct TokenResponse {
    access_token: String,
    #[serde(default)]
    token_type: Option<String>,
    #[serde(default)]
    expires_in: Option<i64>,
    #[serde(default)]
    refresh_token: Option<String>,
    #[serde(default)]
    scope: Option<String>,
}

/// The credential of a successful token response.
fn tokens(status: u16, body: &Value, now: i64) -> Result<Credential, CliError> {
    if !(200..300).contains(&status) || error_code(body).is_some() {
        return Err(oauth_error(status, body));
    }
    let token = TokenResponse::deserialize(body).map_err(CliError::decode)?;
    Ok(Credential {
        access_token: Some(token.access_token),
        refresh_token: token.refresh_token,
        expires_at: token.expires_in.map(|seconds| now + seconds),
        token_type: token.token_type,
        scopes: token
            .scope
            .map(|scope| scope.split_whitespace().map(str::to_owned).collect())
            .unwrap_or_default(),
        ..Credential::default()
    })
}

/// The `error` of an RFC 6749 error response, which some servers send with a 200.
fn error_code(body: &Value) -> Option<&str> {
    body.get("error")?.as_str()
}

fn oauth_error(status: u16, body: &Value) -> CliError {
    let status = if status < 400 { 400 } else { status };
    CliError::api(status, &serde_json::to_vec(body).unwrap_or_default())
}

/// POSTs a form, returning the status and the body as JSON (a string when it is not).
async fn post_form(url: &Url, form: &[(&str, &str)]) -> Result<(u16, Value), CliError> {
    let body = url::form_urlencoded::Serializer::new(String::new())
        .extend_pairs(form)
        .finish();
    let request = Request::post(url.as_str())
        .header(header::CONTENT_TYPE, "application/x-www-form-urlencoded")
        .header(header::ACCEPT, "application/json")
        .body(Full::new(Bytes::from(body)))
        .map_err(|error| CliError::invalid_request(format!("{url}: {error}")))?;
    let client = HttpClient::builder(TokioExecutor::new()).build(connector());
    let network = |error: Box<dyn std::error::Error + Send + Sync>| {
        CliError::network(format!("{url}: {error}")).with_source(error)
    };
    let exchange = async {
        let response = client
            .request(request)
            .await
            .map_err(|e| network(e.into()))?;
        let status = response.status().as_u16();
        let bytes = response
            .into_body()
            .collect()
            .await
            .map_err(|e| network(e.into()))?
            .to_bytes();
        Ok::<_, CliError>((status, bytes))
    };
    let (status, bytes) = tokio::time::timeout(REQUEST_TIMEOUT, exchange)
        .await
        .map_err(|_| CliError::timeout())??;
    let body = serde_json::from_slice(&bytes)
        .unwrap_or_else(|_| Value::String(String::from_utf8_lossy(&bytes).into_owned()));
    Ok((status, body))
}

/// HTTPS over the platform's roots with ring, like the SDK's connector; plain HTTP too.
fn connector() -> hyper_rustls::HttpsConnector<HttpConnector> {
    let provider = rustls::crypto::CryptoProvider::get_default()
        .cloned()
        .unwrap_or_else(|| std::sync::Arc::new(rustls::crypto::ring::default_provider()));
    let builder = match hyper_rustls::HttpsConnectorBuilder::new()
        .with_provider_and_native_roots(provider.clone())
    {
        Ok(builder) => builder,
        Err(_) => hyper_rustls::HttpsConnectorBuilder::new().with_tls_config(
            rustls::ClientConfig::builder_with_provider(provider)
                .with_safe_default_protocol_versions()
                .expect("the default provider supports the default protocol versions")
                .with_root_certificates(rustls::RootCertStore::empty())
                .with_no_client_auth(),
        ),
    };
    let mut http = HttpConnector::new();
    http.enforce_http(false);
    builder.https_or_http().enable_http1().wrap_connector(http)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pkce_follows_rfc_7636() {
        let verifier = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";
        assert_eq!(
            pkce_challenge(verifier),
            "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"
        );
        let token = random_token(32).unwrap();
        assert_eq!(token.len(), 43);
        assert_ne!(token, random_token(32).unwrap());
    }

    #[test]
    fn the_authorization_request_carries_pkce_state_and_scopes() {
        let client = Client::new("cli", "https://auth.acme.dev/token").scopes(&["read", "write"]);
        let browser = Browser::new(client, "https://auth.acme.dev/authorize?audience=api");
        let url = browser
            .authorization_request(None, "http://127.0.0.1:9/callback", "verifier", "st")
            .unwrap();
        let params: Vec<(String, String)> = url.query_pairs().into_owned().collect();
        let get = |name: &str| {
            params
                .iter()
                .find(|(key, _)| key == name)
                .map(|(_, value)| value.as_str())
        };
        assert_eq!(get("audience"), Some("api"));
        assert_eq!(get("response_type"), Some("code"));
        assert_eq!(get("client_id"), Some("cli"));
        assert_eq!(get("redirect_uri"), Some("http://127.0.0.1:9/callback"));
        assert_eq!(
            get("code_challenge"),
            Some(pkce_challenge("verifier").as_str())
        );
        assert_eq!(get("code_challenge_method"), Some("S256"));
        assert_eq!(get("state"), Some("st"));
        assert_eq!(get("scope"), Some("read write"));
    }

    #[test]
    fn relative_urls_resolve_against_the_base_url() {
        let at = |url, base| endpoint(url, base).map(String::from);
        let api = Some("https://api.acme.dev/v1");
        assert_eq!(
            at("https://auth.acme.dev/token", api).unwrap(),
            "https://auth.acme.dev/token"
        );
        assert_eq!(
            at("/oauth/token", api).unwrap(),
            "https://api.acme.dev/oauth/token"
        );
        assert_eq!(
            at("oauth/token", api).unwrap(),
            "https://api.acme.dev/oauth/token"
        );
        assert_eq!(
            at("oauth/token", Some("https://api.acme.dev/v1/")).unwrap(),
            "https://api.acme.dev/v1/oauth/token"
        );
        assert_eq!(
            at("/oauth/token", None).unwrap_err().message(),
            "the OAuth URL `/oauth/token` is relative to the API's, and there is no base URL: pass --base-url"
        );
    }

    #[test]
    fn redirects_must_carry_the_state() {
        assert!(redirect_code("/favicon.ico", "s").is_none());
        assert_eq!(
            redirect_code("/callback?code=c%2F1&state=s", "s")
                .unwrap()
                .unwrap(),
            "c/1"
        );
        let message = |target| {
            redirect_code(target, "s")
                .unwrap()
                .unwrap_err()
                .message()
                .to_owned()
        };
        assert_eq!(
            message("/callback?code=c&state=forged"),
            "login failed: the redirect's state does not match"
        );
        assert_eq!(
            message("/callback?code=c"),
            message("/callback?code=c&state=forged")
        );
        assert_eq!(
            message("/callback?error=access_denied&error_description=No&state=s"),
            "login failed: access_denied: No"
        );
        assert_eq!(
            message("/callback?state=s"),
            "login failed: the redirect has no code"
        );
    }

    #[test]
    fn token_responses_become_credentials() {
        let body = serde_json::json!({
            "access_token": "at", "token_type": "Bearer", "expires_in": 3600,
            "refresh_token": "rt", "scope": "read write"
        });
        let credential = tokens(200, &body, 1000).unwrap();
        assert_eq!(credential.access_token.as_deref(), Some("at"));
        assert_eq!(credential.expires_at, Some(4600));
        assert_eq!(credential.scopes, ["read", "write"]);
        let error = tokens(200, &serde_json::json!({"error": "invalid_grant"}), 0).unwrap_err();
        assert_eq!(error.status(), Some(400));
        assert_eq!(error.message(), "API error 400: invalid_grant");
        let decode = tokens(200, &serde_json::json!({}), 0).unwrap_err();
        assert_eq!(decode.kind(), super::super::error::ErrorKind::Decode);
    }

    #[test]
    fn device_polling_honors_pending_slow_down_and_expiry() {
        assert_eq!(poll("acme", 400, "authorization_pending", 5).unwrap(), 5);
        assert_eq!(poll("acme", 400, "slow_down", 5).unwrap(), 10);
        let message = |code| poll("acme", 400, code, 5).unwrap_err().message().to_owned();
        assert_eq!(
            message("expired_token"),
            "the code expired before the login completed: run `acme auth login` again"
        );
        assert_eq!(
            message("access_denied"),
            "the login was denied: run `acme auth login` again"
        );
        assert_eq!(message("invalid_client"), "API error 400: invalid_client");
    }
}
